.novo-thinking-pill {
  min-width: min(20rem, calc(100vw - 2rem));
  background: linear-gradient(112deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.015) 48%, rgba(127, 211, 255, 0.045));
  box-shadow: 0 16px 52px var(--primary),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: 0 16px 52px color-mix(in srgb, var(--primary) 13%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
  }
}
.novo-thinking-pill__dots {
  display: inline-flex;
  align-items: baseline;
  gap: 2px;
  margin-left: 3px;
  vertical-align: baseline;
}
.novo-thinking-pill__dots i {
  display: inline-block;
  width: 3px;
  height: 3px;
  border-radius: 999px;
  background: currentColor;
  opacity: 0.34;
  animation: novo-thinking-dot 1.15s ease-in-out infinite;
}
.novo-thinking-pill__dots i:nth-child(2) {
  animation-delay: 0.16s;
}
.novo-thinking-pill__dots i:nth-child(3) {
  animation-delay: 0.32s;
}
@keyframes novo-thinking-dot {
  0%, 56%, 100% {
    opacity: 0.28;
    transform: translateY(0) scale(0.8);
  }
  28% {
    opacity: 0.95;
    transform: translateY(-1px) scale(1);
  }
}
:root[data-novo-motion='reduced'] [data-app-viewport] .novo-thinking-pill__dots i,
:root[data-novo-motion='off'] [data-app-viewport] .novo-thinking-pill__dots i {
  animation: none;
  opacity: 0.6;
  transform: none;
}
.novo-thinking-pill__fields {
  position: absolute;
  inset: -65%;
  overflow: hidden;
  pointer-events: none;
  opacity: 0.88;
  contain: paint;
}
.novo-thinking-pill__field {
  position: absolute;
  width: 58%;
  aspect-ratio: 1;
  border-radius: 999px;
  opacity: 0.56;
  filter: blur(24px) saturate(135%);
  will-change: transform;
}
.novo-thinking-pill__field--one {
  top: 11%;
  left: 4%;
  background: var(--primary);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in srgb, var(--primary) 78%, #59f0d0 22%);
  }
  animation: novo-thinking-orbit-one 7.4s ease-in-out infinite alternate;
}
.novo-thinking-pill__field--two {
  right: 3%;
  top: 3%;
  background: color-mix(in srgb, #7c3aed 64%, #ff4fa3 36%);
  animation: novo-thinking-orbit-two 9.2s ease-in-out infinite alternate;
}
.novo-thinking-pill__field--three {
  left: 31%;
  bottom: 1%;
  background: color-mix(in srgb, #f6d365 48%, #fda085 52%);
  animation: novo-thinking-orbit-three 11.2s ease-in-out infinite alternate;
}
.novo-thinking-pill__fields[data-active='false'] .novo-thinking-pill__field {
  animation-play-state: paused;
  will-change: auto;
}
[data-thinking-pill-state='searching'] .novo-thinking-pill__field--one {
  opacity: 0.72;
}
[data-thinking-pill-state='planning'] .novo-thinking-pill__field--two {
  opacity: 0.7;
}
[data-thinking-pill-state='acting'] .novo-thinking-pill__field--three {
  opacity: 0.74;
}
[data-thinking-pill-state='reconnecting'] .novo-thinking-pill__fields {
  filter: saturate(0.65);
}
[data-thinking-pill-state='error'] .novo-thinking-pill__fields {
  filter: hue-rotate(118deg) saturate(0.8);
}
@keyframes novo-thinking-orbit-one {
  from {
    transform: translate3d(-8%, 4%, 0) scale(0.92);
  }
  to {
    transform: translate3d(66%, 14%, 0) scale(1.18);
  }
}
@keyframes novo-thinking-orbit-two {
  from {
    transform: translate3d(7%, -6%, 0) scale(1.08);
  }
  to {
    transform: translate3d(-64%, 28%, 0) scale(0.9);
  }
}
@keyframes novo-thinking-orbit-three {
  from {
    transform: translate3d(-12%, 24%, 0) scale(0.84);
  }
  to {
    transform: translate3d(34%, -28%, 0) scale(1.12);
  }
}
